define("format_selfstudy/nuggets_app", ["exports"], function(exports) {
    Object.defineProperty(exports, "__esModule", {value: true});
    exports.init = void 0;


/**
 * Lern-Nuggets full-screen app: home overview + typed card player.
 *
 * Implements the two navigation models from the IG Metall design handoff —
 * Model A (snap full-screen, default) and Model B (story tap) — plus quiz
 * answering, the memo bookmark toggle, streak counting and adaptive chrome
 * colour. Learner state is persisted client-side (localStorage) for this
 * prototype.
 *
 * @module format_selfstudy/nuggets_app
 */
const init = (config) => {
    const app = document.querySelector('.nq-app');
    if (!app) {
        return;
    }

    const navModel = config.navModel === 'story' ? 'story' : 'snap';
    const storageKey = config.storageKey || 'format_selfstudy_nq';
    const reduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    app.setAttribute('data-navmodel', navModel);

    const home = app.querySelector('[data-screen="home"]');
    const players = Array.from(app.querySelectorAll('[data-screen="nugget"]'));
    let player = null;      // active player element
    let cardsEl = null;     // active scroll container
    let cards = [];         // active card elements
    let idx = 0;

    // --- persistence -------------------------------------------------------

    const defaults = () => ({streak: 5, geschafft: 12, nuggets: {}});
    let state = defaults();
    try {
        const raw = window.localStorage.getItem(storageKey);
        if (raw) {
            state = Object.assign(defaults(), JSON.parse(raw));
        }
    } catch (e) {
        state = defaults();
    }
    const save = () => {
        try {
            window.localStorage.setItem(storageKey, JSON.stringify(state));
        } catch (e) {
            return;
        }
    };
    const nuggetState = (key) => {
        if (!state.nuggets[key]) {
            state.nuggets[key] = {idx: 0, answers: {}, gemerkt: false};
        }
        return state.nuggets[key];
    };

    // --- screens -----------------------------------------------------------

    const showScreen = (name, key) => {
        home.hidden = name !== 'home';
        players.forEach((p) => {
            p.hidden = !(name === 'nugget' && p.getAttribute('data-nugget') === key);
        });
    };

    const start = (key) => {
        player = players.find((p) => p.getAttribute('data-nugget') === key) || players[0];
        if (!player) {
            return;
        }
        showScreen('nugget', player.getAttribute('data-nugget'));
        cardsEl = player.querySelector('[data-cards]');
        cards = Array.from(player.querySelectorAll('.nq-card'));
        restoreNuggetState();
        idx = 0;
        cardsEl.scrollTo({top: 0, behavior: 'auto'});
        updateChrome();
        window.scrollTo(0, 0);
    };

    const goHome = () => {
        showScreen('home');
        player = null;
    };

    // --- navigation within a nugget ---------------------------------------

    const clientH = () => (cardsEl ? cardsEl.clientHeight : window.innerHeight);

    const goTo = (i) => {
        if (!cardsEl) {
            return;
        }
        const target = Math.max(0, Math.min(cards.length - 1, i));
        cardsEl.scrollTo({top: target * clientH(), behavior: reduced ? 'auto' : 'smooth'});
        // Snap derives idx from scroll; story sets it directly.
        if (navModel === 'story') {
            idx = target;
            updateChrome();
        }
    };
    const next = () => goTo(idx + 1);
    const prev = () => goTo(idx - 1);

    const onScroll = () => {
        if (!cardsEl) {
            return;
        }
        const i = Math.round(cardsEl.scrollTop / clientH());
        if (i !== idx && i >= 0 && i < cards.length) {
            idx = i;
            updateChrome();
        }
    };

    // --- chrome ------------------------------------------------------------

    const updateChrome = () => {
        if (!player) {
            return;
        }
        const chrome = player.querySelector('.nq-chrome');
        const count = player.querySelector('.nq-chrome-count');
        const segs = player.querySelectorAll('.nq-seg');
        if (count) {
            count.textContent = (idx + 1) + ' / ' + cards.length;
        }
        segs.forEach((seg, i) => {
            seg.classList.toggle('nq-seg-on', i <= idx);
        });
        const dark = cards[idx] && cards[idx].getAttribute('data-dark') === '1';
        if (chrome) {
            chrome.style.color = dark ? '#ffffff' : '#3C3C3C';
        }
        // Persist last index.
        if (player) {
            nuggetState(player.getAttribute('data-nugget')).idx = idx;
            save();
        }
    };

    // --- quiz / memo restore ----------------------------------------------

    const applyQuiz = (wrap, chosen) => {
        const correct = parseInt(wrap.getAttribute('data-correct'), 10);
        const options = Array.from(wrap.querySelectorAll('.nq-quiz-option'));
        const isRight = chosen === correct;
        options.forEach((opt, i) => {
            opt.classList.remove('nq-quiz-correct', 'nq-quiz-wrong', 'nq-quiz-dim');
            if (i === correct) {
                opt.classList.add('nq-quiz-correct');
            } else if (i === chosen) {
                opt.classList.add('nq-quiz-wrong');
            } else {
                opt.classList.add('nq-quiz-dim');
            }
            opt.disabled = true;
        });
        const feedback = wrap.querySelector('.nq-quiz-feedback');
        if (feedback) {
            feedback.textContent = isRight ?
                wrap.getAttribute('data-feedback-correct') : wrap.getAttribute('data-feedback-wrong');
            feedback.classList.toggle('nq-quiz-feedback-right', isRight);
            feedback.classList.toggle('nq-quiz-feedback-wrong', !isRight);
            feedback.hidden = false;
        }
        const weiter = wrap.querySelector('.nq-quiz-weiter');
        if (weiter) {
            weiter.hidden = false;
        }
    };

    const restoreNuggetState = () => {
        if (!player) {
            return;
        }
        const st = nuggetState(player.getAttribute('data-nugget'));
        player.querySelectorAll('.nq-quiz-wrap').forEach((wrap) => {
            const q = wrap.getAttribute('data-q');
            if (st.answers && typeof st.answers[q] === 'number') {
                applyQuiz(wrap, st.answers[q]);
            }
        });
        if (st.gemerkt) {
            player.querySelectorAll('.nq-memo-toggle').forEach((btn) => setMemo(btn, true));
        }
    };

    const setMemo = (btn, on) => {
        btn.classList.toggle('nq-memo-on', on);
        btn.textContent = on ? 'GEMERKT' : 'MERKEN';
    };

    // --- streak reflection -------------------------------------------------

    const reflectStreak = () => {
        const label = home && home.querySelector('.nq-streak-label');
        const countEl = home && home.querySelector('.nq-streak-count');
        const bars = home ? home.querySelectorAll('.nq-streak-bar') : [];
        if (label) {
            label.textContent = state.streak + ' TAGE AM STÜCK';
        }
        if (countEl) {
            countEl.textContent = state.geschafft + ' Nuggets';
        }
        bars.forEach((bar, i) => bar.classList.toggle('nq-streak-bar-on', i < state.streak));
    };

    const finish = () => {
        state.streak += 1;
        state.geschafft += 1;
        save();
        reflectStreak();
        goHome();
    };

    // --- events (delegated on the app root) --------------------------------

    app.addEventListener('click', (event) => {
        const startBtn = event.target.closest('[data-start]');
        if (startBtn) {
            start(startBtn.getAttribute('data-start'));
            return;
        }
        if (event.target.closest('.nq-close')) {
            goHome();
            return;
        }
        if (event.target.closest('[data-finish]')) {
            finish();
            return;
        }
        if (event.target.closest('[data-next]')) {
            next();
            return;
        }
        const tap = event.target.closest('[data-tap]');
        if (tap && navModel === 'story') {
            if (tap.getAttribute('data-tap') === 'next') {
                next();
            } else {
                prev();
            }
            return;
        }
        const option = event.target.closest('.nq-quiz-option');
        if (option && !option.disabled) {
            const wrap = option.closest('.nq-quiz-wrap');
            const chosen = parseInt(option.getAttribute('data-opt'), 10);
            applyQuiz(wrap, chosen);
            if (player) {
                const st = nuggetState(player.getAttribute('data-nugget'));
                st.answers = st.answers || {};
                st.answers[wrap.getAttribute('data-q')] = chosen;
                save();
            }
            return;
        }
        const memo = event.target.closest('.nq-memo-toggle');
        if (memo) {
            const on = !memo.classList.contains('nq-memo-on');
            setMemo(memo, on);
            if (player) {
                nuggetState(player.getAttribute('data-nugget')).gemerkt = on;
                save();
            }
            return;
        }
        const play = event.target.closest('.nq-play');
        if (play) {
            play.classList.toggle('nq-play-active');
            return;
        }
    });

    // Snap model: track index from scroll position.
    players.forEach((p) => {
        const container = p.querySelector('[data-cards]');
        if (container) {
            container.addEventListener('scroll', () => {
                if (player && container === cardsEl) {
                    onScroll();
                }
            }, {passive: true});
        }
    });

    // Desktop: arrow keys page through the cards.
    document.addEventListener('keydown', (event) => {
        if (!player) {
            return;
        }
        if (event.key === 'ArrowDown' || event.key === 'ArrowRight') {
            event.preventDefault();
            next();
        } else if (event.key === 'ArrowUp' || event.key === 'ArrowLeft') {
            event.preventDefault();
            prev();
        } else if (event.key === 'Escape') {
            goHome();
        }
    });

    // Model B swaps the cover swipe hint wording.
    if (navModel === 'story') {
        app.querySelectorAll('.nq-swipe-text').forEach((el) => {
            el.textContent = 'RECHTS TIPPEN';
        });
        app.querySelectorAll('.nq-swipe-chevron').forEach((el) => {
            el.textContent = '›';
        });
    }

    reflectStreak();
};

    exports.init = init;
});
